using System;
using System.Linq;
using UnityEngine;
public sealed partial class GridShiftCompany:MonoBehaviour {
 public DeliveryManager Manager{get;private set;}public GridShiftCampaignBalance Balance{get;private set;}public CompanyCampaignState State{get;private set;}=new CompanyCampaignState();public GridShiftFinance Finance{get;private set;}public GridShiftMissions Missions{get;private set;}public bool Ready{get;private set;}public event Action Changed;
 public double Day=>WorldSession.Instance!=null?WorldSession.Instance.CalendarDays:0;
 readonly System.Collections.Generic.Dictionary<string,CompanyVehicleHealth> healthCache=new System.Collections.Generic.Dictionary<string,CompanyVehicleHealth>();float nextTick;public static bool SuppressIntro;
 public int Employees=>State.employees.Count(e=>e.hired);public int Drivers=>State.employees.Count(e=>e.hired&&e.role=="Motorista");public int Capacity=>3+Manager.Progression.Level("fleet");
 public float Handling=>State.employees.Any(e=>e.hired&&e.role=="Operador logístico")?.85f:1;
 public bool Mechanic=>State.employees.Any(e=>e.hired&&e.role=="Mecânico");
 void Awake(){Manager=GetComponent<DeliveryManager>();Balance=Resources.Load<GridShiftCampaignBalance>("GridShiftCampaignBalance");if(Balance==null)Balance=ScriptableObject.CreateInstance<GridShiftCampaignBalance>();Finance=GetComponent<GridShiftFinance>();if(Finance==null)Finance=gameObject.AddComponent<GridShiftFinance>();Missions=GetComponent<GridShiftMissions>();if(Missions==null)Missions=gameObject.AddComponent<GridShiftMissions>();if(GetComponent<GridShiftCampaignWorld>()==null)gameObject.AddComponent<GridShiftCampaignWorld>();}
 public void Initialize(CompanyCampaignState saved,bool fresh){State=saved??new CompanyCampaignState();healthCache.Clear();Ready=true;Finance.Initialize();Missions.Initialize();if(saved==null){if(!fresh)State.introSeen=true;SeedEmployees();if(fresh)Manager.TryChangeMoney(Balance.startingCash,"capital-inicial","Capital","Capital inicial da GridShift Logistics");}if(fresh&&!State.introSeen&&!SuppressIntro&&!GridShiftTutorial.Active)StartCoroutine(Missions.Introduction());NotifyChanged();}
 void SeedEmployees(){if(State.employees.Count>0)return;State.employees.Add(new CompanyEmployee{id="ana",name="Ana Torres",role="Motorista",salary=8,benefit="Opera um veículo",hired=true});State.employees.Add(new CompanyEmployee{id="bruno",name="Bruno Costa",role="Motorista",salary=8,benefit="Opera um veículo",hired=true});State.employees.Add(new CompanyEmployee{id="lia",name="Lia Ramos",role="Motorista",salary=10,benefit="Opera um veículo pesado",hired=true});State.employees.Add(new CompanyEmployee{id="rui",name="Rui Martins",role="Mecânico",salary=12,benefit="Reparos custam 25% menos"});State.employees.Add(new CompanyEmployee{id="elisa",name="Elisa Souza",role="Operador logístico",salary=12,benefit="Carga e descarga 15% mais rápidas"});State.employees.Add(new CompanyEmployee{id="marcos",name="Marcos Lima",role="Gerente",salary=15,benefit="Reduz multas por atraso em 50%"});State.employees.Add(new CompanyEmployee{id="davi",name="Davi Alves",role="Motorista",salary=9,benefit="Opera outro veículo"});State.employees.Add(new CompanyEmployee{id="otavio",name="Otávio Melo",role="Motorista",salary=10,benefit="Opera outro veículo"});State.employees.Add(new CompanyEmployee{id="nina",name="Nina Silva",role="Motorista",salary=9,benefit="Opera outro veículo"});}
 void Update(){if(!Ready||Manager.Restoring||Time.time<nextTick)return;nextTick=Time.time+1;Finance.Tick();Missions.Tick();}
 public void NotifyChanged(){Changed?.Invoke();Manager.Changed();}
 public void Save(){Manager.GetComponent<DeliveryPersistence>()?.RequestSave();}
 public void Reputation(int delta){if(delta>0&&!Manager.Restoring)GridShiftAudio.Play("Reputation_Up","SFX",.22f,4);State.reputation=Mathf.Clamp(State.reputation+delta,0,100);NotifyChanged();}
 public bool Employee(string id,bool hire,out string error){Finance.Tick();error=null;var e=State.employees.FirstOrDefault(x=>x.id==id);if(e==null){error="Funcionário inexistente.";return false;}if(e.hired==hire){error="Contratação já está neste estado.";return false;}if(hire){if(Employees>=Capacity+2){error="Amplie a frota/garagem antes de contratar mais pessoas.";return false;}if(!Manager.TryChangeMoney(-e.salary,"hire:"+id+":"+Guid.NewGuid().ToString("N"),"Contratação","Admissão de "+e.name)){error="Saldo insuficiente para admissão.";return false;}}else if(e.role=="Motorista"&&(Drivers<=1||Manager.fleet.Count(v=>v!=null&&v.Order!=null)>=Drivers)){error="Mantenha um motorista e conclua as viagens antes de reduzir a equipe.";return false;}e.hired=hire;GridShiftAudio.Play(hire?"Employee_Hired":"UI_Cancel","SFX",.4f);NotifyChanged();Save();return true;}
 public CompanyVehicleHealth Health(string id){if(healthCache.TryGetValue(id,out var h))return h;h=State.vehicles.FirstOrDefault(v=>v.id==id);if(h==null){h=new CompanyVehicleHealth{id=id};State.vehicles.Add(h);}healthCache[id]=h;return h;}
 public bool CanDrive(CompanyVehicle v){if(!Ready)return true;var h=Health(v.id);return h.fuel>0&&h.condition>0;}
 public bool CanOperate(CompanyVehicle v){if(!Ready)return true;var h=Health(v.id);return h.fuel>0&&h.condition>5&&h.maintenanceUntil<=Day&&Manager.fleet.IndexOf(v)<Drivers;}
 public void Distance(CompanyVehicle v,float meters){if(!Ready||meters<=0||meters>30)return;var h=Health(v.id);h.meters+=meters;h.fuel=Mathf.Max(0,h.fuel-meters/1000*(v.kind==FleetKind.Truck?Balance.truckFuelPerKm:Balance.carFuelPerKm));h.condition=Mathf.Max(0,h.condition-meters/1000*Balance.wearPerKm);}
 public bool Service(string id,bool repair,out string error){error=null;var v=Manager.fleet.FirstOrDefault(x=>x!=null&&x.id==id);if(v==null){if(id==GridShiftPlayerVan.VehicleId&&Manager.GetComponent<GridShiftActiveOperations>()!=null)return Manager.GetComponent<GridShiftActiveOperations>().VanService(repair,out error);error="Veículo inexistente.";return false;}var h=Health(id);if(h.maintenanceUntil>Day){error="Veículo já está em manutenção.";return false;}if(repair&&v.Order!=null&&h.condition>0){error="Conclua a entrega antes da manutenção; abastecer continua disponível.";return false;}float cost=repair?(100-h.condition)*Balance.repairPerPoint*(Mechanic?.75f:1):(100-h.fuel)/100*(v.kind==FleetKind.Truck?Balance.truckRefuel:Balance.carRefuel);if(cost<.01f){error="Serviço desnecessário: veículo já está em boas condições.";return false;}if(!Manager.TryChangeMoney(-cost,"service:"+Guid.NewGuid().ToString("N"),repair?"Manutenção":"Combustível",id)){error="Saldo insuficiente.";return false;}if(repair)h.maintenanceUntil=Day+Balance.maintenanceGameHours/24;else{h.fuel=100;GridShiftAudio.Play("Service_Completed","SFX",.3f);}NotifyChanged();Save();return true;}
 public void FinishServices(){foreach(var h in State.vehicles)if(h.maintenanceUntil>0&&h.maintenanceUntil<=Day){h.maintenanceUntil=0;h.condition=100;GridShiftAudio.Play("Service_Completed","SFX",.35f,2);Manager.Notify("Manutenção concluída · "+h.id);}}
 public DeliveryOffer EventOffer(){var e=State.eventOffer;return Ready&&e!=null&&Day<=State.eventExpiry&&!Manager.orders.Any(o=>o.requestId=="offer:"+e.id)?e:null;}
 public CompanyCampaignState Snapshot(){return new CompanyCampaignState{version=State.version,reputation=State.reputation,act=State.act,complete=State.complete,introSeen=State.introSeen,closedWeeks=State.closedWeeks,merchantPoint=State.merchantPoint,deliveryPoint=State.deliveryPoint,selectedMission=State.selectedMission,news=State.news,eventOffer=State.eventOffer,eventExpiry=State.eventExpiry,nextRecoveryDay=State.nextRecoveryDay,ledger=State.ledger.Skip(Math.Max(0,State.ledger.Count-100)).ToList(),bills=State.bills.Where(b=>!b.paid).Concat(State.bills.Where(b=>b.paid).Reverse().Take(30)).ToList(),weeks=State.weeks.Skip(Math.Max(0,State.weeks.Count-52)).ToList(),employees=State.employees,vehicles=State.vehicles,missions=State.missions};}
 public bool Command(string op,string id,out string error){error=null;switch(op){case "pay-bill":return Finance.Pay(id,out error);case "defer-bill":return Finance.Defer(id,out error);case "hire":return Employee(id,true,out error);case "dismiss":return Employee(id,false,out error);case "refuel":return Service(id,false,out error);case "repair":return Service(id,true,out error);case "read-mission":return Missions.ReadOpportunity(out error);case "start-side":return Missions.StartSideContract(id,out error);case "start-mission":return Missions.StartContract(id,out error);case "confirm-mission":return Missions.Claim(id,out error);case "select-mission":return Missions.Select(id,out error);case "recovery":return Finance.Recovery(out error);default:error="Ação administrativa desconhecida.";return false;}}
}







